  void SetUp() override {
    worker_ = std::thread([this] { processor_.RunUntilDrained(); });
  }
  void TearDown() override {
    if (worker_.joinable()) worker_.join();  // never leave a joinable thread at scope exit
  }
  QueueProcessor processor_;
  std::thread worker_;
};

TEST_F(QueueProcessorTest, DrainsAllEnqueuedItems) {
  processor_.Enqueue(...);
  processor_.Enqueue(...);
  processor_.SignalShutdown();  // tell the loop to finish
  worker_.join();               // wait here, before asserting
  EXPECT_TRUE(processor_.Empty());
  EXPECT_EQ(processor_.ProcessedCount(), 2);
}
```

