```cpp
std::promise<void> done;
std::thread worker([this, p = std::move(done)]() mutable {
  drain(queue);
  p.set_value();
});
// ...push work...
done.get_future().wait();   // or .get() to also rethrow an exception
worker.join();
EXPECT_TRUE(queue.empty());
```

